from scipy.optimize import minimize_scalar
def build(w):
    s=np.sin(w*t); c=np.cos(w*t); sq=np.sqrt(P)
    T={'1':np.ones_like(t),'t':t,'t2':t**2,'s':s,'c':c,'ts':t*s,'tc':t*c}
    Pb={'1':np.ones_like(P),'P':P,'P2':P**2,'sq':sq}
    names=[];cols=[]
    for pn in Pb:
        for tn in T:
            names.append(pn+'*'+tn); cols.append(Pb[pn]*T[tn])
    return np.column_stack(cols),names
def err(w):
    A,_=build(w)
    x=np.linalg.lstsq(A,dP_dt,rcond=None)[0]
    return np.mean((dP_dt-A@x)**2)/np.var(dP_dt)
